/* --- assets/js/exporters.js --- */
(function () {
  "use strict";

  const Log = window.LabFlowLogger?.child("export") || {debug(){},info(){},warn(){},error(){}};
  const encoder = new TextEncoder();
  const palettes = {
    blue:{name:"Scientific Blue",hex:"5B82FF",strong:"3268F5",dark:"101827",light:"EAF0FF"}, green:{name:"Laboratory Green",hex:"35B985",strong:"159568",dark:"0E2720",light:"E6F7F0"},
    violet:{name:"Research Violet",hex:"9470EE",strong:"7049D5",dark:"21183B",light:"F0EBFD"}, red:{name:"Signal Red",hex:"E96672",strong:"CF414F",dark:"32161B",light:"FDEBED"},
    teal:{name:"Instrument Teal",hex:"28ADA7",strong:"087F7B",dark:"0D2828",light:"E4F6F5"}, amber:{name:"Analytical Amber",hex:"E2A43B",strong:"B9790C",dark:"31240D",light:"FCF3DF"},
    cyan:{name:"Spectral Cyan",hex:"35AEE5",strong:"147FAA",dark:"102936",light:"E6F5FC"}, rose:{name:"Materials Rose",hex:"DB67A1",strong:"B73E79",dark:"351529",light:"FBEAF3"}
  };
  const concat = (arrays) => { const total=arrays.reduce((sum,item)=>sum+item.length,0); const output=new Uint8Array(total); let offset=0; arrays.forEach((item)=>{output.set(item,offset);offset+=item.length;}); return output; };
  const u16 = (value) => new Uint8Array([value&255,value>>>8&255]);
  const u32 = (value) => new Uint8Array([value&255,value>>>8&255,value>>>16&255,value>>>24&255]);
  let crcTable;
  function crc(data) { if(!crcTable){crcTable=new Uint32Array(256);for(let n=0;n<256;n++){let value=n;for(let k=0;k<8;k++)value=value&1?0xedb88320^(value>>>1):value>>>1;crcTable[n]=value>>>0;}}let value=0xffffffff;for(const byte of data)value=crcTable[(value^byte)&255]^(value>>>8);return(value^0xffffffff)>>>0; }
  function dosTime() { const now=new Date(); const year=Math.max(1980,now.getFullYear()); return {time:now.getHours()<<11|now.getMinutes()<<5|now.getSeconds()>>1,date:(year-1980)<<9|(now.getMonth()+1)<<5|now.getDate()}; }
  function zipBytes(files) { const local=[];const central=[];let offset=0;for(const file of files){const name=encoder.encode(file.name);const data=file.data instanceof Uint8Array?file.data:encoder.encode(String(file.data));const checksum=crc(data);const stamp=dosTime();const record=concat([u32(0x04034b50),u16(20),u16(0),u16(0),u16(stamp.time),u16(stamp.date),u32(checksum),u32(data.length),u32(data.length),u16(name.length),u16(0),name,data]);local.push(record);central.push(concat([u32(0x02014b50),u16(20),u16(20),u16(0),u16(0),u16(stamp.time),u16(stamp.date),u32(checksum),u32(data.length),u32(data.length),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]));offset+=record.length;}const directory=concat(central);return concat([...local,directory,u32(0x06054b50),u16(0),u16(0),u16(files.length),u16(files.length),u32(directory.length),u32(offset),u16(0)]); }
  function download(value, name) {
    const blob=value instanceof Blob?value:new Blob([value]);
    const link=document.createElement("a");
    const objectUrl=URL.createObjectURL(blob);
    link.href=objectUrl;link.download=name;document.body.append(link);
    Log.info("download.started", { name, bytes: blob.size, mime: blob.type || "application/octet-stream" });
    try { link.click(); Log.info("download.dispatched", { name }); }
    catch (error) { Log.error("download.failed", { name, error }); throw error; }
    finally { link.remove(); setTimeout(()=>URL.revokeObjectURL(objectUrl),1500); }
  }
  const yamlString = (value) => typeof value === "number" || typeof value === "boolean" ? String(value) : `"${String(value ?? "").replace(/\\/g,"\\\\").replace(/"/g,'\\"')}"`;
  function projectYaml(project, pipeline) { const completed=Math.ceil(project.progress/100*pipeline.steps.length);return ["schema: labflow.project.v1",`id: ${yamlString(project.id)}`,`name: ${yamlString(project.name)}`,`pipeline: ${yamlString(pipeline.id)}`,`pipeline_version: ${yamlString(pipeline.version)}`,`status: ${yamlString(project.status)}`,`progress: ${project.progress}`,`owner: ${yamlString(project.owner)}`,`objective: ${yamlString(project.objective)}`,"counts:",`  samples: ${project.samples}`,`  measurements: ${project.measurements}`,`  findings: ${project.findings}`,"steps:",...pipeline.steps.flatMap((step,index)=>[`  - id: ${yamlString(step.id)}`,`    status: ${index<completed?"completed":"available"}`,`    output: ${yamlString(step.output)}`])].join("\n")+"\n"; }
  function jsonl(project, data) { return data.map((row)=>JSON.stringify({project_id:project.id,measurement_type:"JV summary",...row})).join("\n")+"\n"; }
  function csv(data) { const keys=Object.keys(data[0]||{});const quote=(value)=>/[",\n]/.test(String(value))?`"${String(value).replace(/"/g,'""')}"`:value;return keys.join(",")+"\n"+data.map((row)=>keys.map((key)=>quote(row[key])).join(",")).join("\n")+"\n"; }
  function nomadYaml(project) { return `definitions:\n  name: LabFlow project export\ndata:\n  project_id: ${yamlString(project.id)}\n  project_name: ${yamlString(project.name)}\n  source: LabFlow static research workspace\n  upload_state: preview\n`; }

  Log.info("module.ready", { palettes: Object.keys(palettes).length });
  window.LabFlowExport = {palettes, download, projectYaml, jsonl, csv, nomadYaml, zipBytes, zipStore:(files,type="application/zip")=>new Blob([zipBytes(files)],{type})};
})();
;

/* --- assets/js/state.js --- */
(function () {
  "use strict";

  const Log = window.LabFlowLogger?.child("state") || {debug(){},info(){},warn(){},error(){}};
  const clone = (value) => value === undefined ? undefined : JSON.parse(JSON.stringify(value));
  let settings = {};
  let projects;
  let currentUser;
  let workspaceUsers;
  const reports = new Map();
  let assistantMessages = [];

  window.LabFlowState = {
    getSettings: (fallback = {}) => ({ ...clone(fallback), ...clone(settings) }),
    saveSettings(value) { settings = clone(value); Log.debug("settings.saved", { keys: Object.keys(value || {}) }); return true; },
    getUser(fallback = {}) {
      if (currentUser === undefined) currentUser = clone(fallback);
      return clone(currentUser);
    },
    saveUser(value) { currentUser = clone(value); Log.debug("user.saved", { id: value?.id, role: value?.role }); return true; },
    getUsers(fallback = []) {
      if (workspaceUsers === undefined) workspaceUsers = clone(fallback);
      return clone(workspaceUsers);
    },
    saveUsers(value) { workspaceUsers = clone(value); Log.debug("users.saved", { count: value?.length || 0 }); return true; },
    getProjects(fallback) {
      if (projects === undefined) projects = clone(fallback);
      return clone(projects);
    },
    saveProjects(value) { projects = clone(value); Log.debug("projects.saved", { count: value?.length || 0 }); return true; },
    getReport(projectId, fallback = {}) {
      return { ...clone(fallback), ...clone(reports.get(projectId) || {}) };
    },
    saveReport(projectId, value) { reports.set(projectId, clone(value)); Log.debug("report.saved", { projectId, sections: value?.sections?.length || 0 }); return true; },
    getAssistantMessages: () => clone(assistantMessages),
    saveAssistantMessages(value) { assistantMessages = clone(value.slice(-20)); Log.debug("assistant.saved", { count: assistantMessages.length }); return true; },
    reset() {
      settings = {};
      projects = undefined;
      currentUser = undefined;
      workspaceUsers = undefined;
      reports.clear();
      assistantMessages = [];
      Log.info("state.reset");
    }
  };
})();
;

/* Lightweight documentation metadata for global search. */
window.LabFlowDocs=[{"id":"readme","title":"LabFlow","path":"README.md","group":"Overview","updated":"05 Aug 2026","status":"Current","description":"LabFlow is a static research workspace designed by **Matteo Ginesi** to make laboratory projects easier to plan, inspect, compare and report. The proof of concept runs from checked-in HTML, CSS and JavaScript, uses no CDN, sends no automatic request and retains no browser state after reload."},{"id":"project","title":"Project model and architecture","path":"docs/PROJECT.md","group":"Overview","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow turns the structure of laboratory work into an inspectable product model. It demonstrates how a researcher can move from a project objective to prepared materials, experiments, evidence, analysis and export without losing identifiers, provenance or human control."},{"id":"ui-ux-guidelines","title":"UI and interaction guidelines","path":"docs/UI_UX_GUIDELINES.md","group":"Overview","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow should feel like calibrated laboratory instrumentation: compact, sober and precise. Small radii, low controls, clear separators, dense tables and restrained accents support scanning. Decoration is secondary to identifiers, state, evidence and next actions."},{"id":"pipeline-catalog","title":"Pipeline catalog","path":"docs/PIPELINE_CATALOG.md","group":"Pipelines","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow pipelines describe **how work is organised**, not how pages are styled. A pipeline supplies stable identifiers, ordered steps, completion outputs and the renderer contract used by a Project. Shared HTML, CSS, scientific components, reports and export rules remain part of the application rather than being copied into each YAML file."},{"id":"pipeline-chose","title":"CHOSE Perovskite Workflow","path":"docs/PIPELINE_CHOSE.md","group":"Pipelines","updated":"05 Aug 2026","status":"Reviewed","description":"The CHOSE pipeline is LabFlow’s primary domain workflow for perovskite research. It turns reusable laboratory definitions into traceable experiment executions, validated result sets and evidence-linked reports without mixing planned and actual data."},{"id":"pipeline-quick","title":"Quick Measurement Review","path":"docs/PIPELINE_QUICK.md","group":"Pipelines","updated":"05 Aug 2026","status":"Reviewed","description":"Quick Measurement Review is a deliberately small example pipeline. It proves that LabFlow can host a focused scientific review without copying the CHOSE workflow or changing the shared application shell."},{"id":"pipelines-and-data","title":"Pipelines, records and provenance","path":"docs/PIPELINES_AND_DATA.md","group":"Pipelines","updated":"05 Aug 2026","status":"Reviewed","description":"A pipeline describes workflow: ordered steps, labels, expected outputs and the shared project view used by each step. It does not duplicate HTML, component styling or export layouts. Pipeline steps organise work around domain records; they never replace the identities of a Process, Experiment, Result Set or Report."},{"id":"robotics","title":"Robotics capability","path":"docs/ROBOTICS.md","group":"Capabilities","updated":"05 Aug 2026","status":"Reviewed","description":"Robotics is a top-level LabFlow capability, parallel to AI & Models. It demonstrates how a laboratory can simulate, configure, execute and document robotic operations while preserving the same Project, Process, Experiment and evidence model used elsewhere in the platform."},{"id":"ai-ml-foundation","title":"AI, machine learning, deep learning and Vision foundation","path":"docs/AI_ML_FOUNDATION.md","group":"Capabilities","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow treats AI readiness as a consequence of ordinary laboratory work. Researchers continue to use **Workspace → Project → Process → Experiment**; LabFlow captures stable identifiers, units, provenance, files, transformations, labels and outcomes behind that workflow."},{"id":"ai-reports-and-export","title":"Lab Assistant, diagrams, reports and export","path":"docs/AI_REPORTS_AND_EXPORT.md","group":"Capabilities","updated":"05 Aug 2026","status":"Reviewed","description":"Ask LabFlow is the knowledge-facing part of the wider AI-ready foundation. The **AI & Models** workspace also demonstrates dataset snapshots, model versions, training runs and prediction review. These capabilities share evidence, provenance and human-control rules but remain different scientific record types. See `AI_ML_FOUNDATION.md`."},{"id":"theme-integration","title":"Theme integration","path":"docs/THEME_INTEGRATION.md","group":"Engineering","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow uses semantic tokens so components describe purpose instead of choosing isolated colors. Content defaults to light while the application shell remains dark. Eight palettes tint accents and shell depth without changing scientific status meanings."},{"id":"javascript-logging","title":"JavaScript logging and diagnostics","path":"docs/JAVASCRIPT_LOGGING.md","group":"Engineering","updated":"05 Aug 2026","status":"Reviewed","description":"LabFlow includes one local JavaScript diagnostic system for the whole static POC. It writes structured entries to the browser console and keeps a bounded in-memory copy for inspection. It never transmits, persists or uploads logs."},{"id":"validation-checklist","title":"Validation checklist","path":"docs/VALIDATION_CHECKLIST.md","group":"Engineering","updated":"05 Aug 2026","status":"Reviewed","description":"Use this checklist after changes to behavior, data contracts, pipelines, documentation, themes, diagrams or exporters. Refresh every affected checked-in browser snapshot before testing."}];
